"""Runbook: the step-by-step procedure people follow to run a plan, generated by code from the plan.

The tool proposes; people decide. Every gate in the runbook ends in a question that only a person answers, and nothing in
the procedure lets a later step run before an earlier one was recorded. The text is deterministic (no LLM), so two plans
with the same core have the same runbook for the core part.
"""
from __future__ import annotations

from hunting.plan.schema import HuntPlan, Query, RunbookStep, Stage

_GATE_QUESTION = {
    "impact": "Giai đoạn này là dấu hiệu thành công / hậu khai thác. Nếu có kết quả: có chuyển sự cố sang IR không? (công cụ chỉ gợi ý, người quyết định)",
    "indicator": "Giai đoạn này chỉ chứng minh có nỗ lực khai thác. Có ghi nhận và chạy vòng pivot (REFINE) để tìm hậu quả không?",
    "context": "Giai đoạn này là nhiễu nền mong đợi. Ghi nhận, không coi là xâm nhập. Có sang giai đoạn kế tiếp không?",
}


def _query_step(n: int, q: Query, plan: HuntPlan, optional: bool) -> RunbookStep:
    cap = plan.limits.max_rows_per_query
    do = [
        f"Mở queries.bound.spl, chạy đúng truy vấn {q.query_id} (nguồn {q.data_source}). Không sửa SPL: muốn sửa thì dừng và quay lại R0 để duyệt lại.",
        "Chạy riêng từng truy vấn, đợi xong rồi mới chạy cái kế tiếp (không chạy song song nhiều truy vấn).",
        f"Nếu chạy quá {plan.limits.query_timeout_s} giây: huỷ job và ghi status=timeout.",
    ]
    if optional:
        do.insert(0, "CHỈ chạy nếu bạn đã chấp nhận gợi ý này của LLM ở bước R0; nếu không, bỏ qua bước này và ghi 'skipped'.")
    return RunbookStep(
        step_id=f"R{n}", kind="query", title=f"Chạy {q.query_id}: {q.purpose}", do=do, query_ids=[q.query_id],
        record=["status (ok / error / timeout)", "row_count", f"truncated (true nếu chạm trần {cap} dòng)",
                "tối đa 25 dòng mẫu đầu, bỏ dữ liệu nhạy cảm không cần thiết (không dán toàn bộ log)"],
        stop_if=["status là error hoặc timeout: ghi lại, không tự thử lại vô hạn",
                 f"kết quả chạm trần {cap} dòng: dừng giai đoạn, thu hẹp (cửa sổ, host, giá trị) rồi duyệt lại"],
        optional=optional,
    )


def _gate_step(n: int, stage: Stage) -> RunbookStep:
    optional = stage.origin == "llm"
    stop_if = ["một truy vấn của giai đoạn lỗi hoặc chưa chạy: kết luận về giai đoạn này chưa có giá trị, chạy lại trước khi đi tiếp"]
    if stage.significance == "impact" and not optional:
        stop_if.insert(0, "bất kỳ truy vấn nào có kết quả: DỪNG mở rộng, giữ nguyên bằng chứng, báo người phụ trách IR")
    return RunbookStep(
        step_id=f"R{n}", kind="gate", title=f"Cổng {stage.stage_id}: đánh giá giai đoạn '{stage.name}'",
        do=["Đối chiếu kết quả các truy vấn của giai đoạn với phần 'Điểm dừng' của giai đoạn trong plan.md.",
            "Ghi nhận kết luận của người chạy (có / không có dấu hiệu, lý do) trước khi sang giai đoạn kế tiếp."]
        + (["Giai đoạn này là gợi ý của LLM: kết quả chỉ để tham khảo, không dùng để leo thang."] if optional else []),
        record=["kết luận của giai đoạn do người chạy viết"], stop_if=stop_if,
        human_decision=_GATE_QUESTION.get(stage.significance, _GATE_QUESTION["indicator"]), optional=optional,
    )


def build_runbook(plan: HuntPlan) -> list[RunbookStep]:
    steps: list[RunbookStep] = []

    def nxt() -> int:
        return len(steps)

    core = [s for s in plan.stages if s.origin == "core"]
    suggested = [s for s in plan.stages if s.origin == "llm"]
    todo = [f"Việc người phải tự làm: {t}" for t in plan.manual_todo]
    steps.append(RunbookStep(
        step_id="R0", kind="precheck", title="Duyệt kế hoạch (người, trước khi chạy bất cứ thứ gì)",
        do=[
            "Đọc plan.md từ đầu đến cuối, kể cả mục 'Đã loại bỏ / ghi chú của bộ kiểm tra'.",
            "Đối chiếu mục 'Hệ thống nào có thể bị ảnh hưởng' với tài sản thật: có sản phẩm và phiên bản này không? Nếu không thì dừng và ghi 'không áp dụng'.",
            "Đọc từng truy vấn lõi (nguồn gốc core): tên trường (CIM) có khớp dữ liệu của bạn không, chuỗi tìm có đúng thứ nạn nhân thật sự nhận không.",
            *( [f"Với từng gợi ý của LLM ({', '.join(s.stage_id for s in suggested)}): chấp nhận hoặc bỏ, ghi lại quyết định cho từng cái."] if suggested else [] ),
            *todo,
            "Ghi plan_digest ở đầu plan.md vào biên bản duyệt: kết quả trả về phải nhắc lại đúng giá trị này.",
        ],
        record=["tên người duyệt (approved_by)", "thời điểm duyệt (approved_at)", "plan_digest", "danh sách gợi ý LLM được chấp nhận / bỏ"],
        stop_if=["sản phẩm hoặc phiên bản không có trong hệ thống", "không hiểu một truy vấn làm gì: không chạy thứ không hiểu"],
        human_decision="Có duyệt kế hoạch này để chạy không? Công cụ không tự chạy bất cứ truy vấn nào.",
    ))
    steps.append(RunbookStep(
        step_id=f"R{nxt()}", kind="bind", title="Gắn chỉ mục và cửa sổ thời gian, kiểm tra truy vấn sau khi gắn",
        do=[
            "Chọn cửa sổ thời gian cần xem (mặc định là lookback của kế hoạch). Cửa sổ phải có đầu và cuối rõ ràng và không rộng quá 90 ngày.",
            "Ánh xạ mỗi nguồn dữ liệu của kế hoạch sang đúng MỘT chỉ mục thật. Không dùng '*', không dùng chỉ mục nội bộ (_internal, _audit).",
            "Chạy: python main.py bind --plan plan.json --map web=<chỉ mục> --map endpoint=<chỉ mục> ... [--earliest ISO --latest ISO] --out queries.bound.spl",
            "Nếu ở R0 bạn đã chấp nhận gợi ý của LLM, thêm --accept-llm L1,L2 (đúng các mã đã chấp nhận); mặc định chỉ gắn phần lõi.",
            "Lệnh bind từ chối: index=*, thiếu earliest/latest, thiếu 'head N', chỉ mục sai định dạng, placeholder chưa gắn. Nếu bị từ chối thì sửa ánh xạ, đừng sửa tay SPL.",
            "Mở queries.bound.spl và đọc lại từng dòng một lần nữa trước khi dán vào Splunk.",
        ],
        record=["ánh xạ nguồn → chỉ mục đã dùng", "cửa sổ earliest / latest đã dùng"],
        stop_if=["bind báo lỗi", "không chắc chỉ mục nào chứa nguồn dữ liệu đó", "chỉ mục quá lớn và chưa thử trên cửa sổ ngắn"],
        human_decision="Chỉ mục và cửa sổ thời gian có đúng phạm vi được phép tìm không?",
    ))
    for probe in plan.coverage_probes:
        steps.append(RunbookStep(
            step_id=f"R{nxt()}", kind="coverage", title=f"Độ phủ {probe.query_id}: nguồn '{probe.data_source}' có dữ liệu không",
            do=[f"Chạy truy vấn {probe.query_id} trước mọi truy vấn phát hiện của nguồn này.",
                "Kết quả rỗng ở nguồn không có dữ liệu không chứng minh điều gì: đó là lý do truy vấn này chạy trước."],
            query_ids=[probe.query_id],
            record=["status", "row_count", "các sourcetype thấy được và first_seen / last_seen"],
            stop_if=["nguồn rỗng: các giai đoạn dùng nguồn này chưa có giá trị, ghi 'cần bổ sung dữ liệu' (COLLECT_DATA)"],
            human_decision="Nếu nguồn thiếu dữ liệu: bổ sung telemetry hay chấp nhận giới hạn này?",
            optional=probe.origin == "llm",
        ))
    for stage in [*core, *suggested]:
        optional = stage.origin == "llm"
        for q in stage.queries:
            steps.append(_query_step(nxt(), q, plan, optional))
        steps.append(_gate_step(nxt(), stage))
    steps.append(RunbookStep(
        step_id=f"R{nxt()}", kind="handoff", title="Điền kết quả và gửi để xác minh",
        do=[
            "Điền result.template.json: plan_digest, approved_by, approved_at, executor, và kết quả từng truy vấn (đúng query_id).",
            "Truy vấn không chạy thì để status=skipped; không xoá khỏi danh sách và không đoán kết quả.",
            "Chạy: python main.py verify --plan plan.json --results results.json",
        ],
        record=["results.json đã điền", "verification.md"],
        stop_if=["verify báo REJECT_RESULTS: kết quả không thuộc kế hoạch đã duyệt, kiểm tra plan_id và plan_digest"],
    ))
    steps.append(RunbookStep(
        step_id=f"R{nxt()}", kind="decision", title="Đọc verification.md và quyết định (người)",
        do=["Đọc 'Quyết định' và 'Việc con người cần quyết định' trong verification.md; công cụ chỉ đưa gợi ý có lý do.",
            "Nếu quyết định là REFINE: kế hoạch vòng sau là một kế hoạch MỚI, có plan_digest mới; duyệt lại từ R0.",
            "Nếu ACCEPT_NO_EVIDENCE: ghi 'không thấy bằng chứng trong phạm vi đã quét', không ghi 'sạch'."],
        record=["quyết định cuối cùng, người quyết định, thời điểm, lý do"],
        human_decision="Quyết định cuối cùng (chuyển IR / dừng / chạy vòng tiếp / bổ sung dữ liệu) thuộc về người. Công cụ không thực hiện hành động nào.",
    ))
    return steps


def render_runbook_md(plan: HuntPlan) -> str:
    lines = [
        f"# Quy trình thực hiện từng bước — {plan.title}", "",
        f"- Plan `{plan.plan_id}` · vòng {plan.iteration} · plan_digest `{plan.provenance.plan_digest or '(chưa tính)'}`",
        "- Quy trình có người trong vòng lặp: công cụ chỉ đưa ra đề xuất; mọi mục **Quyết định của người** do người trả lời.",
        "- Làm tuần tự, không bỏ bước, ghi lại phần **Ghi lại** trước khi sang bước sau.", "",
    ]
    for s in plan.runbook:
        lines += [f"## {s.step_id}. {s.title}" + (" *(tuỳ chọn: gợi ý của LLM)*" if s.optional else ""), ""]
        lines += [f"- [ ] {d}" for d in s.do]
        if s.record:
            lines += ["", "**Ghi lại:**", *[f"- {r}" for r in s.record]]
        if s.stop_if:
            lines += ["", "**Dừng lại nếu:**", *[f"- {r}" for r in s.stop_if]]
        if s.human_decision:
            lines += ["", f"**Quyết định của người:** {s.human_decision}", "", "- [ ] Đã quyết định:  ____________  (người)  ____________  (thời điểm)"]
        lines.append("")
    return "\n".join(lines) + "\n"
